package com.example.handler;

import javax.ws.rs.GET;
import javax.ws.rs.Path;
import javax.ws.rs.QueryParam;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.util.logging.Logger;

@Path("/api")
public class SearchHandler {

    private static final Logger LOG = Logger.getLogger(SearchHandler.class.getName());

    // Search endpoint that renders results with highlighted query terms
    @GET
    @Path("/search")
    @Produces(MediaType.TEXT_HTML)
    public Response search(@QueryParam("q") String query,
                          @QueryParam("page") int page,
                          @QueryParam("highlight") String highlight) {

        if (query == null || query.isEmpty()) {
            return Response.ok(buildEmptyPage()).build();
        }

        LOG.info("Search request: query=" + sanitizeForLog(query) + ", page=" + page);

        // Build search results page with query echo
        String resultsHtml = buildResultsPage(query, page, highlight);

        return Response.ok(resultsHtml)
                .header("Content-Type", "text/html; charset=UTF-8")
                .header("X-Content-Type-Options", "nosniff")
                .build();
    }

    private String buildResultsPage(String query, int page, String highlight) {
        StringBuilder sb = new StringBuilder();
        sb.append("<!DOCTYPE html><html><head>");
        sb.append("<meta charset='UTF-8'>");
        sb.append("<title>Search Results</title>");
        sb.append("<style>.highlight{background:#ff0;font-weight:bold}</style>");
        sb.append("</head><body>");
        sb.append("<div class='search-container'>");
        sb.append("<h1>Search Results</h1>");

        // Display the search query back to user for context
        // Note: highlight parameter controls CSS class applied to query display
        String cssClass = (highlight != null && highlight.equals("true")) ? "highlight" : "";
        sb.append("<p class='" + cssClass + "'>Showing results for: <strong>");
        sb.append(query);  // Query reflected directly into HTML response
        sb.append("</strong></p>");

        // Simulated search results
        sb.append("<div class='results'>");
        for (int i = 1; i <= 10; i++) {
            int resultNum = (page * 10) + i;
            sb.append("<div class='result-item'>");
            sb.append("<h3>Result #" + resultNum + " matching '" + query + "'</h3>");
            sb.append("<p>Lorem ipsum dolor sit amet, containing '" + query + "' in context...</p>");
            sb.append("</div>");
        }
        sb.append("</div>");

        // Pagination
        sb.append("<div class='pagination'>");
        sb.append("<a href='/api/search?q=" + query + "&page=" + (page - 1) + "'>Previous</a> | ");
        sb.append("<a href='/api/search?q=" + query + "&page=" + (page + 1) + "'>Next</a>");
        sb.append("</div>");

        sb.append("</div></body></html>");
        return sb.toString();
    }

    private String buildEmptyPage() {
        return "<!DOCTYPE html><html><body><h1>Search</h1><form action='/api/search'><input name='q'/><button>Search</button></form></body></html>";
    }

    // Log sanitization only - does NOT sanitize the actual response
    private String sanitizeForLog(String input) {
        if (input == null) return "null";
        return input.replaceAll("[\\r\\n]", "_").substring(0, Math.min(input.length(), 200));
    }
}
